func:
var err = msg.error || {};
node.warn("Error capturado en el flujo (gemelo preservado): " + (err.message || JSON.stringify(err)));
if (global.get("gemelo")) {
    return null;
}
return msg;

var gemelo = global.get("gemelo");
if (gemelo && gemelo.estado_actual) { node.status({fill:"green",shape:"dot",text:"Gemelo ya activo"}); return null; }
gemelo = {
    "ultimo_update": new Date().toISOString(),
    "estado_actual": {
        "co2": 200,
        "distancia": 100,
        "sonido": 30,
        "persona": false,
        "persona_reconocida": false,
        "persona_nombre": null,
        "led": false,
        "buzzer": false
    },
    "umbrales": {
        "co2": { "limite": 400, "direccion": "mayor", "unidad": "ppm" },
        "sonido": { "limite": 80, "direccion": "mayor", "unidad": "dB" },
        "distancia": { "limite": 20, "direccion": "menor", "unidad": "cm" }
    },
    "historial_1h": [],
    "alertas_activas": [],
    "prediccion_30min": {
        "co2": null,
        "distancia": null
    },
    "resumen_llm": "Sistema iniciado"
};
global.set("gemelo", gemelo);
node.status({fill:"green",shape:"dot",text:"Gemelo activo"});
return null;

var gemelo = global.get("gemelo") || {};
var payload = msg.payload;
var data = typeof payload === "string" ? JSON.parse(payload) : payload;

if (data) {
    gemelo.ultimo_update = new Date().toISOString();

    if (data.co2 !== undefined) gemelo.estado_actual.co2 = data.co2;
    else if (data.gas !== undefined) gemelo.estado_actual.co2 = data.gas;
    if (data.distancia !== undefined) gemelo.estado_actual.distancia = data.distancia;
    if (data.sonido !== undefined) gemelo.estado_actual.sonido = data.sonido;

    var registro = {
        "ts": new Date().toISOString(),
        "co2": gemelo.estado_actual.co2,
        "distancia": gemelo.estado_actual.distancia,
        "sonido": gemelo.estado_actual.sonido
    };
    gemelo.historial_1h.push(registro);
    if (gemelo.historial_1h.length > 60) {
        gemelo.historial_1h.shift();
    }

    if (data.tipo === "preventiva") {
        gemelo.alertas_activas.push(data.mensaje);
        if (gemelo.alertas_activas.length > 5) gemelo.alertas_activas.shift();
    }

    global.set("gemelo", gemelo);
}
return msg;

var gemelo = global.get("gemelo");
if (!gemelo) return null;
var estado = gemelo.estado_actual;

var debeActuar = false;
var razon = "";

if (estado.co2 > 400) { debeActuar = true; razon = "CO2 alto"; }
else if (estado.sonido > 80) { debeActuar = true; razon = "Sonido alto"; }
else if (estado.distancia < 20) { debeActuar = true; razon = "Distancia baja"; }

if (debeActuar) {
    var ultimaAccion = flow.get("ultima_accion_llm") || 0;
    var ahora = Date.now();
    if (ahora - ultimaAccion > 30000) {
        flow.set("ultima_accion_llm", ahora);
        return { payload: { debeActuar: true, razon: razon } };
    }
}
return { payload: { debeActuar: false } };

var gemelo = global.get("gemelo");
var payload = msg.payload;
if (!gemelo || !payload || !payload.debeActuar) return null;

var e = gemelo.estado_actual;
var prompt = "Eres el sistema de control de una casa inteligente. Tienes 4 sensores: CO2 (MQ7), nivel de sonido, distancia ultrasonica y una camara con reconocimiento facial.\n\n";
prompt += "Estado actual del hogar:\n";
prompt += "- CO2 (MQ7): " + e.co2 + " ppm (umbral de alerta: 400 ppm)\n";
prompt += "- Distancia: " + e.distancia + " cm\n";
prompt += "- Nivel de sonido: " + e.sonido + " dB\n";
prompt += "- Persona detectada por camara: " + (e.persona ? "si" : "no") + (e.persona && e.persona_nombre ? " (" + e.persona_nombre + ")" : "") + "\n";
prompt += "- Hora local: " + new Date().toLocaleTimeString() + "\n\n";
prompt += "Motivo de evaluacion: " + payload.razon + "\n\n";
prompt += "Analiza el estado y responde SOLO en formato JSON valido\n";
prompt += "con exactamente esta estructura:\n";
prompt += JSON.stringify({
    nivel_alerta: "normal|medio|critico",
    activar_led: true,
    activar_buzzer: true,
    mensaje_alerta: "texto corto",
    razonamiento: "explicacion breve"
}, null, 2);

return {
    payload: {
        model: "llama3.2:3b",
        prompt: prompt,
        stream: false,
        format: "json"
    }
};

var gemelo = global.get("gemelo");
var payload = msg.payload;
if (!gemelo || !payload || !payload.response) return null;

try {
    var decision = JSON.parse(payload.response);

    msg1 = { payload: {} };
    msg2 = { payload: {} };
    msg3 = { payload: {} };

    if (decision.activar_led) {
        msg1.payload = { estado: decision.activar_led };
    }
    if (decision.activar_buzzer) {
        msg2.payload = { estado: decision.activar_buzzer };
    }

    msg3.payload = {
        nivel: decision.nivel_alerta || "normal",
        razonamiento: decision.razonamiento || "",
        timestamp: new Date().toISOString()
    };

    gemelo.resumen_llm = decision.razonamiento || "";
    gemelo.ultimo_update = new Date().toISOString();
    global.set("gemelo", gemelo);

    node.status({fill:"blue",shape:"dot",text:decision.nivel_alerta});

    return [[msg1], [msg2], [msg3]];
} catch(e) {
    node.error("Error parseando respuesta LLM: " + e);
    return null;
}

var gemelo = global.get("gemelo");
if (!gemelo) {
    return { payload: { error: "Gemelo no inicializado" }, res: msg.res, req: msg.req, statusCode: 503 };
}
gemelo.prediccion_30min = global.get("prediccion") || gemelo.prediccion_30min;
return { payload: gemelo, res: msg.res, req: msg.req, statusCode: 200 };

var topic = msg.topic || "";
var payload = msg.payload;
var data = typeof payload === "string" ? JSON.parse(payload) : payload;
var gemelo = global.get("gemelo");
if (!gemelo) return null;

if (topic.includes("co2")) {
    gemelo.prediccion_30min.co2 = data.valor;
} else if (topic.includes("distancia")) {
    gemelo.prediccion_30min.distancia = data.valor;
}
global.set("gemelo", gemelo);
return null;

var gemelo = global.get("gemelo");
if (!gemelo) return null;

var e = gemelo.estado_actual;
var pregunta = msg.payload || "";
if (!pregunta) return null;

var contexto = "Datos actuales de los sensores de la casa:\n";
contexto += "- CO2 (sensor MQ7): " + e.co2 + " ppm\n";
contexto += "- Distancia (ultrasonico): " + e.distancia + " cm\n";
contexto += "- Nivel de sonido: " + e.sonido + " dB\n";
contexto += "- Persona detectada por la camara: " + (e.persona ? ("Si" + (e.persona_nombre ? ", identificada como " + e.persona_nombre : ", desconocida")) : "No") + "\n";
contexto += "- LED: " + (e.led ? "Encendido" : "Apagado") + "\n";
contexto += "- Buzzer: " + (e.buzzer ? "Activado" : "Apagado") + "\n\n";
contexto += "Pregunta del usuario: " + pregunta;

return {
    payload: {
        model: "llama3.2:3b",
        system: "Eres el asistente de una casa inteligente. Responde SIEMPRE en espanol, de forma breve, clara y precisa, usando solo los datos de sensores proporcionados. No inventes valores que no esten en el contexto.",
        prompt: contexto,
        stream: false
    }
};

var d = typeof msg.payload === "string" ? JSON.parse(msg.payload) : msg.payload;
if (!d) return null;
var f = [];
if (d.co2 !== undefined) f.push("co2=" + parseFloat(d.co2));
else if (d.gas !== undefined) f.push("co2=" + parseFloat(d.gas));
if (d.distancia !== undefined) f.push("distancia=" + parseFloat(d.distancia));
if (d.sonido !== undefined) f.push("sonido=" + parseFloat(d.sonido));
if (f.length === 0) return null;
msg.payload = "sensor,equipo=equipo2 " + f.join(",");
msg.headers = { "Authorization": "Token smarthome_token_2024", "Content-Type": "text/plain" };
return msg;

var b = msg.payload || {};
var disp = b.dispositivo || "led";
var estado = (b.estado === true || b.estado === "true" || b.estado === "ON" || b.estado === 1);
var mqttMsg = { topic: "smarthome/equipo2/control/" + disp, payload: estado ? "ON" : "OFF" };
msg.payload = { ok: true, dispositivo: disp, estado: estado ? "ON" : "OFF" };
msg.statusCode = 200;
return [mqttMsg, msg];

var b = msg.payload || {};
var estado = String(b.status || 'firing').replace(/[^a-zA-Z0-9_-]/g, '');
var titulo = 'alerta';
try { titulo = (b.alerts && b.alerts[0] && b.alerts[0].labels && b.alerts[0].labels.alertname) || b.title || 'alerta'; } catch(e) {}
node.warn('Alerta Grafana: ' + estado + ' - ' + titulo);
var gemelo = global.get('gemelo');
if (gemelo) {
    gemelo.alertas_activas.push('Grafana: ' + titulo + ' (' + estado + ')');
    if (gemelo.alertas_activas.length > 5) gemelo.alertas_activas.shift();
    global.set('gemelo', gemelo);
}
msg.headers = { 'Authorization': 'Token smarthome_token_2024', 'Content-Type': 'text/plain' };
msg.payload = 'alerta_grafana,estado=' + estado + ' valor=1';
return msg;

if (!Buffer.isBuffer(msg.payload) || msg.payload.length < 100) {
    node.status({fill:'red',shape:'ring',text:'camara no disponible'});
    return null;
}
var b64 = msg.payload.toString('base64');
msg.payload = { image: 'data:image/jpeg;base64,' + b64 };
msg.headers = { 'Content-Type': 'application/json' };
return msg;

var r = msg.payload || {};
var total = r.total_detectados || (r.rostros ? r.rostros.length : 0);
var reconocido = false;
var nombre = null;
if (r.rostros && r.rostros.length) {
    var rec = r.rostros.find(function(x){ return x.reconocido; });
    if (rec) { reconocido = true; nombre = rec.nombre; }
}
var gemelo = global.get('gemelo');
if (gemelo) {
    gemelo.estado_actual.persona = total > 0;
    gemelo.estado_actual.persona_reconocida = reconocido;
    gemelo.estado_actual.persona_nombre = nombre;
    gemelo.ultimo_update = new Date().toISOString();
    global.set('gemelo', gemelo);
}
node.status({fill: total>0?'blue':'grey', shape:'dot', text: total>0 ? ('persona: '+(nombre||'desconocida')) : 'sin persona'});
return { payload: { persona: total>0, reconocida: reconocido, nombre: nombre } };
